def _tab():
    s='<rect x="1" y="1" width="338" height="88" fill="none" stroke="currentColor"/>'
    for y in (31,61):s+='<line x1="1" y1="%d" x2="339" y2="%d" stroke="currentColor" stroke-opacity="0.5"/>'%(y,y)
    for k in range(5):
        x=90+k*50;s+='<line x1="%d" y1="1" x2="%d" y2="89" stroke="currentColor" stroke-opacity="0.5"/>'%(x,x)
    s+='<text x="45" y="21" text-anchor="middle" font-weight="700">Year</text><text x="45" y="51" text-anchor="middle" font-weight="700">Rice</text><text x="45" y="81" text-anchor="middle" font-weight="700">Maize</text>'
    for i,yr in enumerate(_YR):
        x=115+i*50
        s+='<text x="%d" y="21" text-anchor="middle" font-weight="700">%s</text><text x="%d" y="51" text-anchor="middle">%d</text><text x="%d" y="81" text-anchor="middle">%d</text>'%(x,yr,x,_R[i],x,_M[i])
    return '<svg viewBox="0 0 340 90" width="340" height="90" role="img" aria-label="table"><g font-family="sans-serif" font-size="13" fill="currentColor">'+s+'</g></svg>'
